# LinkButton LinkButton Кнопки-ссылки могут отображаться в нескольких размерах и цветах, могут содержать текст и/или иконку. ## Использование Использование Компонент  `LinkButton`  может содержать текст, который указывается в
свойстве  `text` , или любой контент напрямую через  `children` . Свойство text можно использовать вместе со свойствами  `contentLeft`  и  `contentRight` .
С их помощью можно размещать  иконку  слева или справа от текста. ```tsx
import React from 'react';
import { LinkButton } from '@salutejs/sdds-finai';
import { IconDownload } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <LinkButton text="Текст" />

            <LinkButton text="Текст" contentLeft={<IconDownload color="inherit" />} />

            <LinkButton text="Текст" contentRight={<IconDownload color="inherit" />} />

            <LinkButton text="Текст" isLoading />

            <LinkButton text="Текст" isLoading loader={<div>Loader...</div>} />
        </div>
    );
}
```

## Примеры Примеры ### Размер кнопки Размер кнопки Размер кнопки задается с помощью свойства  `size` : ```tsx
import React from 'react';
import { LinkButton } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div>
            <LinkButton text="Кнопка" size="s" />
            <LinkButton text="Кнопка" size="xs" />
            <LinkButton text="Кнопка" size="xxs" />
        </div>
    );
}
```

### Вид кнопки Вид кнопки Вид кнопки задается с помощью свойства  `view` . Доступные значения:  `default` ,  `accent` ,  `secondary` ,  `positive` ,  `warning` ,  `negative` ,  `info` ,  `gradient` .
Значение  `gradient`  окрашивает текст, переданный через свойство  `text` , в акцентный градиент. ```tsx
import React from 'react';
import { LinkButton } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
            <LinkButton text="Кнопка" size="s" view="default" />
            <LinkButton text="Кнопка" size="s" view="accent" />
            <LinkButton text="Кнопка" size="s" view="gradient" />
            <LinkButton text="Кнопка" size="s" view="secondary" />
            <LinkButton text="Кнопка" size="s" view="positive" />
            <LinkButton text="Кнопка" size="s" view="warning" />
            <LinkButton text="Кнопка" size="s" view="negative" />
            <LinkButton text="Кнопка" size="s" view="info" />
        </div>
    );
}
```
